Get-ChildItem -Path d:\enterprise_auth_system\frontend\lib\features -Recurse -Filter *_screen.dart | ForEach-Object { $c = Get-Content $_.FullName -Raw; $m = $c -replace 'const SizedBox\(height: 20\)', 'const SizedBox(height: 8)' -replace 'const SizedBox\(height: 16\)', 'const SizedBox(height: 8)' -replace 'const SizedBox\(height: 24\)', 'const SizedBox(height: 8)' -replace 'padding: const EdgeInsets.all\(24\)', 'padding: const EdgeInsets.all(12)' -replace 'padding: const EdgeInsets.all\(20\)', 'padding: const EdgeInsets.all(12)'; if ($c -ne $m) { Set-Content -Path $_.FullName -Value $m; Write-Output "Updated $($_.Name)" } }
